#include "ksGlobalClampedTimeTask.h"
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Clamped time semantic property failed");}
int main(){using T=ks::GlobalClampedTimeTask;uint64_t cases=0;auto verify=[&](unsigned mode,unsigned time,unsigned base,bool budgets){T t;unsigned children=0,guard=0;auto read=[&](T::Read r)->uint32_t{switch(r){case T::Read::Mode:return mode;case T::Read::Time:return time;case T::Read::Base:return base;case T::Read::Table:check(t.index()==uint8_t((mode-1)*4));return 0x87654321u^t.index();}return 0;};while(t.stage()!=T::Stage::Complete){check(++guard<48);auto child=t.child();if(child!=T::Child::None){if(child==T::Child::Time){auto v=(uint32_t(uint8_t(time<<1))*175*base)>>16;if(v<4)v=4;if(v>0x7ff8)v=0x7ff8;check(t.quantized()==v*256);}if(child==T::Child::Table)check(t.table()==(0x87654321u^uint8_t((mode-1)*4)));check(t.resumeChild());++children;continue;}auto c=t.nextClocks(),s=unsigned(t.stage());if(budgets)check(t.advanceBefore(c-1,read)==0&&unsigned(t.stage())==s);check(t.advanceBefore(c,read)==c);}check(children==2);++cases;};for(unsigned mode=0;mode<256;++mode)for(unsigned time=0;time<256;++time)verify(mode,time,44100,true);for(unsigned base=0;base<65536;++base)for(unsigned time=0;time<256;++time)verify(0,time,base,false);std::cout<<"PASS: "<<cases<<" pure clamped time properties; all mode/time pairs, all256time×65536base pairs, byte shift wrap, unsigned product high, clamp4..7ff8, table index,2child lifetime and budget refusal\n";}
